use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
pub enum ConfigError {
    Parse(ParseIntError),
    OutOfRange(i64),
}

impl From<ParseIntError> for ConfigError {
    fn from(e: ParseIntError) -> Self {
        ConfigError::Parse(e)
    }
}

/// 文字列をポート番号 (1〜65535) として解釈します。
pub fn parse_port(s: &str) -> Result<u16, ConfigError> {
    let n: i64 = s.parse()?;
    if !(1..=65535).contains(&n) {
        return Err(ConfigError::OutOfRange(n));
    }
    Ok(n as u16)
}

description_md:
文字列を柔軟に整数として解釈する関数 `parse_int_flexible` を実装してください。第一候補の解釈に失敗したら、別の形式で再解釈を試みる「フォールバック」パターンの練習です。

仕様は次のとおりです。

1. まず入力 `s` を **10進数の `i64`** としてパースします。成功したらその値を `Ok` で返します。
2. 失敗した場合、`s` が `"0x"` で始まっていれば、`"0x"` を取り除いた残りを **16進数** としてパースします (`i64::from_str_radix(残り, 16)` が使えます)。
3. どちらでも解釈できない場合は `Err(format!("invalid: {s}"))` を返します (`s` は元の入力全体です)。

```rust
