/// 10進数として解釈し、失敗したら "0x" 始まりの16進数として再解釈します。
pub fn parse_int_flexible(s: &str) -> Result<i64, String> {
    s.parse::<i64>().or_else(|_| {
        s.strip_prefix("0x")
            .ok_or_else(|| format!("invalid: {s}"))
            .and_then(|hex| {
                i64::from_str_radix(hex, 16).map_err(|_| format!("invalid: {s}"))
            })
    })
}

