/// 座標が原点・軸上・第何象限にあるかを判定します。
pub fn quadrant(p: (i32, i32)) -> &'static str {
    match p {
        (0, 0) => "原点",
        (_, 0) => "x軸上",
        (0, _) => "y軸上",
        (x, y) if x > 0 && y > 0 => "第1象限",
        (x, y) if x < 0 && y > 0 => "第2象限",
        (x, y) if x < 0 && y < 0 => "第3象限",
        _ => "第4象限",
    }
}

