let req = RequestBuilder::new("https://example.com").build();
assert_eq!(req.method, "GET");       // 何も指定しなければ初期値
assert_eq!(req.timeout_secs, 30);

let req = RequestBuilder::new("https://api.example.com")
    .method("POST")
    .timeout_secs(5)
    .build();
assert_eq!(req.method, "POST");
assert_eq!(req.timeout_secs, 5);
```

