answer_code:
pub fn min_max<T>(items: &[T]) -> Option<(T, T)>
where
    T: Clone + PartialOrd,
{
    let mut iter = items.iter();
    let first = iter.next()?;
    let mut min = first;
    let mut max = first;
    for item in iter {
        if item < min {
            min = item;
        }
        if item > max {
            max = item;
        }
    }
    Some((min.clone(), max.clone()))
}

pub fn debug_join<T>(items: &[T], sep: &str) -> String
where
    T: std::fmt::Debug,
{
    items
        .iter()
        .map(|item| format!("{:?}", item))
        .collect::<Vec<String>>()
        .join(sep)
}

