assert_eq!(Pair::new("apple", "pear").larger_display(), "larger: pear");
assert_eq!(Pair::new(5, 5).larger_display(), "larger: 5"); // 等しいときは x

// 境界を満たさない型でも new は使える (larger_display は呼べない)
struct NoOrd;
let _p = Pair::new(NoOrd, NoOrd);
```

