answer_code:
pub fn digit_sum(n: u64) -> u32 {
    n.to_string()
        .chars()
        .fold(0, |acc, c| acc + c.to_digit(10).unwrap())
}

pub fn product(items: &[i64]) -> i64 {
    items.iter().fold(1, |acc, &x| acc * x)
}

