answer_code:
pub fn top_k_even_square_sum(v: &[i32], k: usize) -> i64 {
    let mut squares: Vec<i64> = v
        .iter()
        .filter(|&&x| x % 2 == 0)
        .map(|&x| (x as i64) * (x as i64))
        .collect();
    squares.sort_unstable_by(|a, b| b.cmp(a));
    squares.iter().take(k).sum()
}

