pub fn run_length_encode(s: &str) -> Vec<(char, usize)> {
    s.chars().fold(Vec::new(), |mut acc, c| {
        match acc.last_mut() {
            Some((prev, count)) if *prev == c => *count += 1,
            _ => acc.push((c, 1)),
        }
        acc
    })
}

