pub struct Record {
    pub name: String,
    pub age: u32,
}

pub fn parse_records(input: &str) -> Result<Vec<Record>, String> {
    input
        .lines()
        .map(|line| {
            let parts: Vec<&str> = line.split(',').collect();
            if parts.len() != 2 {
                return Err(format!("不正な行です: {line}"));
            }
            let name = parts[0].trim().to_string();
            let age = parts[1]
                .trim()
                .parse::<u32>()
                .map_err(|_| format!("年齢を数値に変換できません: {}", parts[1]))?;
            Ok(Record { name, age })
        })
        .collect()
}

