use std::collections::HashMap;

pub fn group_by_initial(words: &[&str]) -> HashMap<char, Vec<String>> {
    let mut map: HashMap<char, Vec<String>> = HashMap::new();
    for &word in words {
        if let Some(initial) = word.chars().next() {
            map.entry(initial).or_insert_with(Vec::new).push(word.to_string());
        }
    }
    map
}

