use std::collections::VecDeque;

pub struct History {
    capacity: usize,
    items: VecDeque<i32>,
}

impl History {
    pub fn new(capacity: usize) -> Self {
        History {
            capacity,
            items: VecDeque::with_capacity(capacity),
        }
    }

    pub fn push(&mut self, value: i32) {
        if self.items.len() == self.capacity {
            self.items.pop_front();
        }
        self.items.push_back(value);
    }

    pub fn items(&self) -> Vec<i32> {
        self.items.iter().copied().collect()
    }
}

pub fn rotate_left(nums: &[i32], n: usize) -> Vec<i32> {
    let mut deque: VecDeque<i32> = nums.iter().copied().collect();
    if !deque.is_empty() {
        deque.rotate_left(n % deque.len());
    }
    deque.into_iter().collect()
}

description_md:
テキスト中の単語の出現頻度を数え、上位 `n` 件を返す関数 `top_n_words` を実装してください。

## 仕様

- 単語は `split_whitespace()` で区切ります (大文字小文字はそのまま区別します)。
- 戻り値は `(単語, 出現回数)` の `Vec<(String, usize)>` です。
- 並び順は **出現回数の降順**、同数の場合は **単語の辞書順 (昇順)** です。
- 異なり語数が `n` 未満ならある分だけ返します。`n == 0` や空テキストでは空の `Vec` を返します。

## 入出力例

```rust
let text = "b a b c a b";
assert_eq!(
    top_n_words(text, 2),
    vec![("b".to_string(), 3), ("a".to_string(), 2)]
);

// apple と pear は同数 2 回 → 辞書順で apple が先
let text = "pear apple pear apple orange";
assert_eq!(
    top_n_words(text, 2),
    vec![("apple".to_string(), 2), ("pear".to_string(), 2)]
);
```

`HashMap` で集計 → `Vec` に変換 → 複合キーでソート → `truncate(n)`、という流れで実装しましょう。

