    type Error = String;

    fn try_from(t: (i32, i32, i32)) -> Result<Self, Self::Error> {
        Ok(Rgb {
            r: check_component(t.0)?,
            g: check_component(t.1)?,
            b: check_component(t.2)?,
        })
    }
}

