#[derive(Debug, PartialEq)]
pub enum List {
    Cons(i32, Box<List>),
    Nil,
}

pub fn from_vec(values: &[i32]) -> List {
    match values.split_first() {
        Some((&head, tail)) => List::Cons(head, Box::new(from_vec(tail))),
        None => List::Nil,
    }
}

pub fn to_vec(list: &List) -> Vec<i32> {
    match list {
        List::Cons(value, rest) => {
            let mut result = vec![*value];
            result.extend(to_vec(rest));
            result
        }
        List::Nil => Vec::new(),
    }
}

pub fn sum(list: &List) -> i32 {
    match list {
        List::Cons(value, rest) => value + sum(rest),
        List::Nil => 0,
    }
}

