pub fn add_from(map: &mut HashMap<String, i32>, src: &str, dst: &str) -> bool {
    // TODO: このままでは E0502 (可変借用と不変借用の衝突) でコンパイルできません。
    // src の値を一時変数にコピーしてから書き込むように直してください。
    if let Some(v) = map.get(src) {
