answer_code:
use std::collections::HashMap;

pub fn add_from(map: &mut HashMap<String, i32>, src: &str, dst: &str) -> bool {
    // 先に値をコピーして map への不変借用を終わらせる (i32 は Copy)
    let v = match map.get(src) {
        Some(&v) => v,
        None => return false,
    };
    // ここではもう map への借用は残っていないので、可変借用を取れる
    *map.entry(dst.to_string()).or_insert(0) += v;
    true
}

