answer_code:
pub fn fib_checked(n: u32) -> Option<u64> {
    if n == 0 {
        return Some(0);
    }
    // a = fib(k-1), b = fib(k) を保ちながら進める
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 1..n {
        let next = a.checked_add(b)?; // 溢れたらここで None が返る
        a = b;
        b = next;
    }
    Some(b)
}

