answer_code:
pub fn my_binary_search(xs: &[i32], target: i32) -> Result<usize, usize> {
    // 不変条件: 答えの位置は常に半開区間 [lo, hi) の中にある
    let (mut lo, mut hi) = (0usize, xs.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if xs[mid] < target {
            lo = mid + 1; // mid は候補から外れる
        } else if xs[mid] > target {
            hi = mid; // mid は候補から外れる (半開区間なので hi = mid)
        } else {
            return Ok(mid);
        }
    }
    Err(lo) // lo == hi が挿入位置
}

