answer_code:
#[derive(Debug, PartialEq, Eq)]
pub enum RpnError {
    UnknownToken(String),
    StackUnderflow,
    DivisionByZero,
}

pub fn eval_rpn(input: &str) -> Result<i64, RpnError> {
    let mut stack: Vec<i64> = Vec::new();

    for token in input.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                // 先に pop した方が右オペランド
                let rhs = stack.pop().ok_or(RpnError::StackUnderflow)?;
                let lhs = stack.pop().ok_or(RpnError::StackUnderflow)?;
                let result = match token {
                    "+" => lhs + rhs,
                    "-" => lhs - rhs,
                    "*" => lhs * rhs,
                    "/" => {
                        if rhs == 0 {
                            return Err(RpnError::DivisionByZero);
                        }
                        lhs / rhs
                    }
                    _ => unreachable!(),
                };
                stack.push(result);
            }
            _ => {
                let value: i64 = token
                    .parse()
                    .map_err(|_| RpnError::UnknownToken(token.to_string()))?;
                stack.push(value);
            }
        }
    }

    // ちょうど 1 個残っているときだけ成功
    match stack.pop() {
        Some(result) if stack.is_empty() => Ok(result),
        _ => Err(RpnError::StackUnderflow),
    }
}

hidden_tests:
#[test]
fn 正常な式を評価できる() {
    assert_eq!(eval_rpn("3 4 +"), Ok(7));
    assert_eq!(eval_rpn("5 1 2 + 4 * + 3 -"), Ok(14));
    assert_eq!(eval_rpn("42"), Ok(42));
    assert_eq!(eval_rpn("-3 2 *"), Ok(-6));
}

#[test]
fn 整数除算は0方向へ切り捨て() {
    assert_eq!(eval_rpn("7 2 /"), Ok(3));
    assert_eq!(eval_rpn("-7 2 /"), Ok(-3));
    assert_eq!(eval_rpn("10 5 2 - /"), Ok(3)); // 10 / (5 - 2)
}

#[test]
fn 各種エラーを返す() {
    assert_eq!(eval_rpn("1 0 /"), Err(RpnError::DivisionByZero));
    assert_eq!(eval_rpn("abc"), Err(RpnError::UnknownToken("abc".to_string())));
    assert_eq!(eval_rpn("1 2 %"), Err(RpnError::UnknownToken("%".to_string())));
    assert_eq!(eval_rpn("1 +"), Err(RpnError::StackUnderflow));
}

#[test]
fn 不完全な式はエラー() {
    assert_eq!(eval_rpn(""), Err(RpnError::StackUnderflow));
    assert_eq!(eval_rpn("   "), Err(RpnError::StackUnderflow));
    assert_eq!(eval_rpn("2 3"), Err(RpnError::StackUnderflow)); // 2 個残る
    assert_eq!(eval_rpn("+"), Err(RpnError::StackUnderflow));
}
